import argparse,json,torch
p=argparse.ArgumentParser(); p.add_argument('artifact'); p.add_argument('kernel'); p.add_argument('--output',default='results/gdn_real_batch_compare.json'); a=p.parse_args(); x=torch.load(a.artifact,map_location='cpu',weights_only=False); y=torch.load(a.kernel,map_location='cpu',weights_only=False)
ho,hs=x['hf_output'],x['hf_state']; ko,ks=y['kernel_output'],y['kernel_state']; row={'output_max_abs_error':float((ho-ko).abs().max()),'state_max_abs_error':float((hs-ks).abs().max()),'output_equal':bool(torch.equal(ho,ko)),'state_equal':bool(torch.equal(hs,ks)),'output_argmax_equal':bool(torch.equal(ho.argmax(-1),ko.argmax(-1))),'kernel_median_seconds':y['median_seconds'],'finite':bool(torch.isfinite(ko).all() and torch.isfinite(ks).all())}; open(a.output,'w').write(json.dumps(row,indent=2)+'\n'); print(json.dumps(row))
